25:         setError(null);
26:         setSourceTime(null);
27:         fetch(getApiUrl(`/api/clip-jobs/${jobId}/clips/${clipIndex}/edl`))
28:             .then((r) => { if (!r.ok) throw new Error('Could not load the current cut.'); return r.json(); })
29:             .then((d) => {
30:                 setSegments(d.segments || []);
31:                 setCanonicalRange(d.canonical_range || null);
32:                 setLoading(false);
33:             })
