49:     const pathKind = (() => {
50:         if (!canonicalRange || segments.length === 0) return null;
51:         const inside = segments.every(
52:             (s) => s.start >= canonicalRange.start - 0.05 && s.end <= canonicalRange.end + 0.05
53:         );
54:         return inside ? 'fast' : 'full';
55:     })();
