62:         setSegments((segs) => segs.map((s, j) => (j === i ? { ...s, [field]: v } : s)));
63:     };
64: 
65:     const addSegment = () => {
66:         setSegments((segs) => {
67:             if (segs.length >= 12) return segs;
68:             const last = segs[segs.length - 1];
69:             const base = last ? last.end : (canonicalRange ? canonicalRange.start : 0);
70:             return [...segs, { start: Math.round(base * 10) / 10, end: Math.round((base + 3) * 10) / 10 }];
71:         });
