123:                         {sourceTime !== null ? (
124:                             <>Preview position = original video <b style={{ color: 'var(--ink)' }}>{sourceTime.toFixed(1)}s</b></>
125:                         ) : (
126:                             <>Play the preview to read exact cut points</>
127:                         )}
128:                     </div>
