156:                                         className="os-input" style={{ width: 90, fontFamily: 'var(--font-mono)' }}
157:                                         aria-label={`Segment ${i + 1} end`}
158:                                     />
159:                                     <span style={{ marginLeft: 'auto', fontSize: '0.75rem', color: 'var(--subtle)', fontFamily: 'var(--font-mono)' }}>
