1: // Configuration for API endpoints
2: // If VITE_API_URL is set (e.g. in production), use it.
3: // Otherwise, default to empty string which means relative paths (proxied in dev).
4: 
5: export const API_BASE_URL = import.meta.env.VITE_API_URL || '';
6: 
7: export const getApiUrl = (path) => {
8:     if (path.startsWith('http')) return path;
9:     // Ensure path starts with / if not present
10:     const normalizedPath = path.startsWith('/') ? path : `/${path}`;
11:     return `${API_BASE_URL}${normalizedPath}`;
