                                                <button onClick={() => nudgeScene(idx, 'right')} className="os-btn os-btn-ghost os-btn-sm" aria-label="Nudge right">
                                                    <ArrowRight size={14} />
                                                </button>
                                            </div>
                                        </div>
                                    );
                                })}
                            </div>

